#!/usr/bin/env python3
# Auto-generated CIFAR-10 inference script for AXU4EV board
import os, mmap, struct, time, ctypes

CLASSES = ['airplane','automobile','bird','cat','deer',
           'dog','frog','horse','ship','truck']

fd  = os.open('/dev/mem', os.O_RDWR | os.O_SYNC)
lib = ctypes.CDLL('libc.so.6')

def _mmap(addr, size):
    p  = addr & ~0xFFF
    sz = (size + 0xFFF) & ~0xFFF
    mm = mmap.mmap(fd, sz, mmap.MAP_SHARED,
                   mmap.PROT_READ | mmap.PROT_WRITE, offset=p)
    return mm, addr & 0xFFF

def wr(addr, val):
    mm, o = _mmap(addr, 4)
    mm[o:o+4] = struct.pack('<I', val); mm.close()

def rd(addr):
    mm, o = _mmap(addr, 4)
    v = struct.unpack('<I', mm[o:o+4])[0]; mm.close(); return v

def flush_write(phys, data):
    mm, o = _mmap(phys, len(data))
    mm[o:o+len(data)] = data
    ptr = ctypes.cast(
        ctypes.addressof(ctypes.c_char.from_buffer(mm)), ctypes.c_void_p)
    lib.msync(ptr, len(data), 4)
    mm.close()

def inv_read(phys, n):
    mm, o = _mmap(phys, n)
    ptr = ctypes.cast(
        ctypes.addressof(ctypes.c_char.from_buffer(mm)), ctypes.c_void_p)
    lib.madvise(ptr, n, 4)
    d = bytes(mm[o:o+n]); mm.close(); return d

DMA      = 0x80040000
SRC_PHYS = 0x66c00000   # 6144 bytes input
DST_PHYS = 0x66c02000   # 32 bytes output (10 x int16 + padding)
IN_BYTES  = 6144
OUT_BYTES = 20          # 10 classes x 2 bytes

def dma_soft_reset():
    wr(DMA+0x00, rd(DMA+0x00) | 0x4)
    wr(DMA+0x30, rd(DMA+0x30) | 0x4)
    for _ in range(500):
        if not (rd(DMA+0x00) & 0x4) and not (rd(DMA+0x30) & 0x4):
            break
        time.sleep(0.002)

def run_inference(payload, label_name, quiet=False):
    assert len(payload) == IN_BYTES
    if not quiet:
        print(f'\n--- Running inference: expected={label_name} ---')
    dma_soft_reset()
    # Write input image with cache flush
    flush_write(SRC_PHYS, payload)
    flush_write(DST_PHYS, b'\x00' * OUT_BYTES)
    # Start S2MM (receive) FIRST
    wr(DMA+0x30, 0x1 | 0x1000)
    wr(DMA+0x48, DST_PHYS); wr(DMA+0x4C, 0)
    wr(DMA+0x58, OUT_BYTES)
    # Start MM2S (send) - triggers HLS processing
    wr(DMA+0x00, 0x1 | 0x1000)
    wr(DMA+0x18, SRC_PHYS); wr(DMA+0x1C, 0)
    wr(DMA+0x28, IN_BYTES)
    # Poll: HLS latency ~13ms, timeout 2s
    for i in range(1000):
        s2mm = rd(DMA+0x34); mm2s = rd(DMA+0x04)
        if (s2mm & 0x1000) and (mm2s & 0x1000): break
        time.sleep(0.002)
    else:
        if not quiet:
            print(f'  TIMEOUT! MM2S_SR=0x{rd(DMA+0x04):08X} S2MM_SR=0x{rd(DMA+0x34):08X}')
        return False
    if not quiet:
        print(f'  Done in {i*2}ms  MM2S_SR=0x{mm2s:08X}  S2MM_SR=0x{s2mm:08X}')
    # Read output with cache invalidate
    raw = inv_read(DST_PHYS, OUT_BYTES)
    scores = [struct.unpack_from('<h', raw, k*2)[0] / 1024.0 for k in range(10)]
    pred = scores.index(max(scores))
    if not quiet:
        print(f'  Scores: {[round(s,3) for s in scores]}')
        print(f'  Prediction: {CLASSES[pred]} (class {pred})')
        print(f'  Correct:    {CLASSES[pred] == label_name}')
    return True

# Test image 0: true label = cat
payload_0 = bytes.fromhex('')

print('--- Warm-up (prime HLS/DMA pipeline, discard result) ---')
if run_inference(payload_0, 'warmup', quiet=True):
    print('  Warm-up OK')
else:
    print('  Warm-up failed (continuing with tests)')
run_inference(payload_0, 'cat')

# Test image 1: true label = ship
payload_1 = bytes.fromhex('')
run_inference(payload_1, 'ship')

# Test image 2: true label = ship
payload_2 = bytes.fromhex('')
run_inference(payload_2, 'ship')

os.close(fd)
print('\nDone.')